<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import AtlasWorld from './components/AtlasWorld.vue';
import CreationTheatre from './components/CreationTheatre.vue';
import SharedPatterns from './components/SharedPatterns.vue';
import Knowledge from './components/Knowledge.vue';
import GeneAtlas from './components/GeneAtlas.vue';
import PatternReading from './components/PatternReading.vue';
import OriginalStudio from './components/OriginalStudio.vue';
import CommunityArchive from './components/CommunityArchive.vue';
const page=ref('home'),catalog=ref<any>({stats:{},patterns:[]}),detail=ref<any>(null),saved=ref<any[]>([]),q=ref(''),filter=ref(''),error=ref(''),busy=ref(false),token=ref(''),report=ref<any>(null),requests=ref<any[]>([]),file=ref<File>(),atlasPattern=ref<any>(null),dimension=ref('场景意象'),theatreRevision=ref(0),articleId=ref(''),editorSeedDesign=ref<any>(null),editorSeedPattern=ref<any>(null),editorRevision=ref(0),communityRevision=ref(0),originFilter=ref('heritage');
const navigation=[{id:'studio',label:'AI 造物台'},{id:'library',label:'纹样基因库'},{id:'atlas',label:'纹样星球'},{id:'original',label:'共创工坊'},{id:'knowledge',label:'纹样书房'},{id:'saved',label:'作品集'}];
const activePage=computed(()=>['original','community'].includes(page.value)?'original':page.value==='home'?'studio':page.value==='detail'?'library':page.value);
async function api(path:string,options:any={}){const r=await fetch('/api'+path,options);if(!r.ok){const b=await r.json().catch(()=>({detail:'暂时无法连接，请重试'}));throw Error(typeof b.detail==='string'?b.detail:'请检查填写内容后重试')}return r.json()}
async function act(fn:()=>Promise<any>){error.value='';busy.value=true;try{await fn()}catch(e:any){error.value=e.message}finally{busy.value=false}}
const patterns=computed(()=>catalog.value.patterns.filter((p:any)=>(originFilter.value==='all'||(p.origin||'heritage')===originFilter.value)&&(!q.value||JSON.stringify(p).toLowerCase().includes(q.value.toLowerCase()))&&(!filter.value||p.imagery.some((i:any)=>i.word===filter.value))));
const labels=computed(()=>Array.from(new Set(catalog.value.patterns.flatMap((p:any)=>p.imagery.filter((i:any)=>i.category===dimension.value).map((i:any)=>i.word)))).slice(0,32));
function locationFor(route:string){return !route||route==='home'?location.pathname:'#'+route}
function setLocation(route:string){if(location.hash.slice(1)!==route)history.pushState(null,'',locationFor(route))}
let navigationRevision=0;
async function routeTo(route:string,push=false,request=++navigationRevision){
 if(request!==navigationRevision)return;
 error.value='';if(route!=='knowledge')articleId.value='';if(push)setLocation(route);
 try{
  if(route.startsWith('pattern/')){const p=await api('/patterns/'+route.slice(8));if(request!==navigationRevision)return;detail.value=p;page.value='detail'}
  else if(route.startsWith('XY-')){const d=await api('/designs/'+route);if(request!==navigationRevision)return;bridgeToTheatre(d);page.value='studio'}
  else if(route==='atlas'){if(!atlasPattern.value){const p=await api('/patterns/PAT-001');if(request!==navigationRevision)return;atlasPattern.value=p}page.value='atlas'}
  else if(route==='saved'){const records=await api('/designs');if(request!==navigationRevision)return;saved.value=records;page.value='saved'}
  else page.value=['knowledge','library','admin','studio','original','community'].includes(route)?route:'home';
  window.scrollTo({top:0,behavior:'instant'});
 }catch(e){if(request===navigationRevision)throw e}
}
function go(route:string){return act(()=>routeTo(route,true))}
function openPattern(id:string){return go('pattern/'+id)}
function readArticle(id:string){articleId.value=id;return go('knowledge')}
let atlasFocusRequest=0;
async function focusAtlas(id:string){const request=++atlasFocusRequest;try{const p=await api('/patterns/'+id);if(request===atlasFocusRequest)atlasPattern.value=p}catch{}}
function atlas(id='PAT-001'){const request=++navigationRevision;return act(async()=>{try{const p=await api('/patterns/'+id);if(request!==navigationRevision)return;atlasPattern.value=p;await routeTo('atlas',true,request)}catch(e){if(request===navigationRevision)throw e}})}
function storeCreation(d:any,state:any){const st={...state,source:undefined};st.history=[...(state.history||[d])];st.cursor=Math.min(state.cursor??st.history.length-1,st.history.length-1);if(JSON.stringify(st).length>1800000)delete st.candidates;while(st.history.length>1&&JSON.stringify(st).length>2200000){if(st.cursor>0){st.history.shift();st.cursor--}else st.history.pop()}try{localStorage.removeItem('xiyu-session-state');localStorage.setItem('xiyu-theatre',JSON.stringify(d));localStorage.setItem('xiyu-session-state',JSON.stringify(st))}catch{try{localStorage.setItem('xiyu-session-state',JSON.stringify({...st,history:[d],cursor:0,candidates:undefined}))}catch{}}}
function bridgeToTheatre(d:any){storeCreation(d,{history:[d],cursor:0,stage:3,wish:d.recipe.prompt,recipient:d.recipe.recipient||'自己',vessel:d.recipe.vessel});theatreRevision.value++}
function restore(d:any){go(d.id)}
const vesselDims:Record<string,[number,number]>={pot:[90,75],tray:[120,120],bookmark:[30,140],box:[80,80],vase:[70,100],pendant:[35,35],lid:[70,70],cup:[70,55],penholder:[75,90],incense:[80,80],jar:[80,90],plaque:[100,130]};
async function usePattern(id:string,knowledgeArticleId?:string){
 const request=++navigationRevision;
 await act(async()=>{try{
  const p=await api('/patterns/'+id);if(request!==navigationRevision)return;
  if(!p.genes.some(canUseGene))throw Error('这份档案目前可供阅读；请选择有可用图元的纹样进行创作。');
  const targetVessel=localStorage.getItem('xiyu-user-vessel')||'pot';
  const [vw,vh]=vesselDims[targetVessel]||[90,75];
  const d=await api('/designs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:p.name,pattern_id:id,auto_match:false,template:p.origin==='contemporary'?'original':'center',count:8,scale:p.origin==='contemporary'?1:.8,spacing:1,color:'#d6e2df',seed:0,vessel:targetVessel,layers:[],rotation:0,width_mm:vw,height_mm:vh,knowledge_article_ids:knowledgeArticleId?[knowledgeArticleId]:[]})});if(request!==navigationRevision)return;
  bridgeToTheatre(d);setLocation(d.id);page.value='studio';articleId.value='';window.scrollTo(0,0);
 }catch(e){if(request===navigationRevision)throw e}})
}
async function chooseAtlasGene(g:any,role:string){
 const request=++navigationRevision;
 await act(async()=>{try{
  const raw=localStorage.getItem('xiyu-theatre');
  const targetVessel=localStorage.getItem('xiyu-user-vessel')||'pot';
  const [vw,vh]=vesselDims[targetVessel]||[90,75];
  if(!raw){const d=await api('/creation/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pattern_id:g.pattern,prompt:g.label,auto_match:false,vessel:targetVessel,color:'#d6e2df',layers:[{pattern_id:g.pattern,code:g.code,role}],width_mm:vw,height_mm:vh})});if(request!==navigationRevision)return;bridgeToTheatre(d);await routeTo('studio',true,request);return;}
  const previous=JSON.parse(raw),r={...previous.recipe,auto_match:false,parent_design_id:previous.id};r.layers=previous.genes.filter((x:any)=>x.role!==role).map((x:any)=>({pattern_id:x.pattern,code:x.code,role:x.role}));r.layers.push({pattern_id:g.pattern,code:g.code,role});
  const d=await api('/creation/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(r)});if(request!==navigationRevision)return;
  const st=JSON.parse(localStorage.getItem('xiyu-session-state')||'{}');st.history=[...(st.history||[]),d].slice(-20);st.cursor=st.history.length-1;st.stage=3;storeCreation(d,st);theatreRevision.value++;await routeTo('studio',true,request);
 }catch(e){if(request===navigationRevision)throw e}})
}
async function admin(){await act(async()=>{report.value=await api('/admin/report',{headers:{Authorization:'Bearer '+token.value}});requests.value=await api('/manufacturing/requests',{headers:{Authorization:'Bearer '+token.value}})})}
async function updateRequest(id:string,status:string){await act(async()=>{await api('/manufacturing/requests/'+id+'/status',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token.value},body:JSON.stringify({status,note:''})});await admin()})}
async function upload(){if(!file.value)return;await act(async()=>{const form=new FormData();form.append('file',file.value!);await api('/admin/import',{method:'POST',headers:{Authorization:'Bearer '+token.value},body:form});await admin()})}
function canUseGene(g:any){return g.type==='图元'&&(g.status==='已确认'||(g.origin==='contemporary'&&g.status==='可复用'))&&g.assets?.some((a:any)=>a.svg)}
async function openOriginal(seed:any=null){const request=++navigationRevision;await act(async()=>{let d=seed;if(d?.preview_only)d=await api('/creation/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d.recipe)});if(request!==navigationRevision)return;editorSeedDesign.value=d;editorSeedPattern.value=null;editorRevision.value++;await routeTo('original',true,request)})}
function editCommunity(p:any){editorSeedDesign.value=null;editorSeedPattern.value=p;editorRevision.value++;go('original')}
async function communitySaved(){communityRevision.value++;try{catalog.value=await api('/catalog')}catch{}}
function knowledgeCreate(id?:string,article?:string){if(id)usePattern(id,article);else go('studio')}
const loadSaved=()=>go('saved');
function focusContent(){document.getElementById('page-content')?.focus();document.getElementById('page-content')?.scrollIntoView()}
function onLocation(){act(()=>routeTo(location.hash.slice(1)))}
onMounted(()=>{window.addEventListener('popstate',onLocation);window.addEventListener('hashchange',onLocation);act(async()=>{catalog.value=await api('/catalog');await routeTo(location.hash.slice(1))})});
onUnmounted(()=>{window.removeEventListener('popstate',onLocation);window.removeEventListener('hashchange',onLocation)});
</script>
<template><div class="app-shell">
<a class="skip-link" href="#page-content" @click.prevent="focusContent">跳至页面内容</a>
<header class="app-header"><a class="app-brand" href="#studio" @click.prevent="go('studio')"><span class="app-seal" aria-hidden="true"><img src="/assets/brand-seal.png" alt=""></span><span>锡语华纹<small class="brand-caption">一意成纹 · 纹入器</small></span></a><nav class="app-nav" aria-label="主导航"><a v-for="item in navigation" :key="item.id" :href="'#'+item.id" :class="{'nav-active':activePage===item.id}" :aria-current="activePage===item.id?'page':undefined" @click.prevent="go(item.id)">{{item.label}}<span v-if="item.id==='studio'" aria-hidden="true"> ↗</span></a></nav></header>
<div v-if="error" role="alert" class="error">{{error}}<button @click="error=''">关闭</button></div><div v-if="busy" class="loading" role="status">正在载入…</div>
<div id="page-content" tabindex="-1"><CreationTheatre :key="theatreRevision" v-show="['home','studio'].includes(page)" @navigate="go" @pattern="openPattern" @read="readArticle"><template #after-workflow="{design:current,stage}"><div class="creation-shortcuts"><button @click="openOriginal()">新建自由绘制</button><button v-if="current&&stage>0" @click="openOriginal(current)">继续绘制当前纹样</button><a href="#community" @click.prevent="go('community')">打开作品库 →</a></div></template></CreationTheatre><OriginalStudio :key="editorRevision" v-show="page==='original'" :seed-design="editorSeedDesign" :seed-pattern="editorSeedPattern" @saved="communitySaved" @navigate="go"/>
<CommunityArchive v-if="page==='community'" :refresh-key="communityRevision" @create="usePattern" @edit="editCommunity" @navigate="go"/><Knowledge v-else-if="page==='knowledge'" :initial-article="articleId" @article-close="articleId=''" @pattern="openPattern" @create="knowledgeCreate"/>
<main v-else-if="page==='atlas'" class="content atlas-page"><AtlasWorld @pattern="openPattern" @choose="chooseAtlasGene" @read="readArticle" @pattern-create="usePattern" @focus-pattern="focusAtlas"/><details v-if="atlasPattern" class="atlas-source-detail"><summary>沿当前纹样深读 · {{atlasPattern.name}}<span>{{atlasPattern.id}} · 基因与意象关系</span></summary><GeneAtlas :pattern="atlasPattern" @gene="openPattern(atlasPattern.id)"/></details><details class="atlas-source-detail"><summary>比较不同纹样中的构图秩序<span>跨纹样的同类结构</span></summary><SharedPatterns :patterns="catalog.patterns" @pattern="openPattern"/></details><div class="atlas-footnotes"><article><span>M / C / S / P</span><h3>基因不是一张图</h3><p>图元描述形，构图描述秩序，语义描述意义，工艺适配描述如何制作。</p></article><article><span>IMG / REL</span><h3>意义需要线索相连</h3><p>每条映射保留出处、证据、权重和状态。点击连线两端的节点，逐条查看依据。</p></article><article><span>候选 ≠ 已确认</span><h3>留下尚未确定的空间</h3><p>虚线表示候选关系。它是进一步研究的线索，不能被当成确定的文化释义。</p></article></div></main>
<main v-else-if="page==='library'" class="content"><p class="eyebrow">PATTERN ARCHIVE / 寻纹</p><h1 class="page-title">中华纹样基因库</h1><p class="subtle">查其形，溯其源，读其意。{{catalog.stats.patterns}} 篇真实标注档案。</p><div class="asset-origin-tabs"><button :class="{active:originFilter==='heritage'}" @click="originFilter='heritage'">传统资料 · {{catalog.stats.patterns}}</button><button :class="{active:originFilter==='contemporary'}" @click="originFilter='contemporary'">当代共创 · {{catalog.stats.community_patterns||0}}</button><button :class="{active:originFilter==='all'}" @click="originFilter='all'">全部资产</button><a href="#community" @click.prevent="go('community')">进入当代创作库 ↗</a></div><div class="search"><input v-model="q" placeholder="搜索纹样、地域、文化寓意…" aria-label="搜索纹样"><button @click="q='';filter=''">清除筛选</button></div><div class="library-dimensions"><button v-for="d in ['场景意象','文化意象','感性意象','地域意象']" :class="{active:dimension===d}" @click="dimension=d;filter=''">{{d}}</button></div><div class="chips"><button :class="{selected:!filter}" @click="filter=''">全部</button><button v-for="l in labels" :class="{selected:filter===l}" @click="filter=String(l)">{{l}}</button></div><p class="subtle">找到 {{patterns.length}} 篇纹样</p><div class="cards library-grid"><button class="pattern-card" :class="{'is-contemporary':p.origin==='contemporary'}" v-for="p in patterns" :key="p.id" @click="openPattern(p.id)"><div class="pattern-art"><img :src="p.images.find((a:any)=>!a.code)?.url||p.images[0]?.url" :alt="p.name" loading="lazy"></div><small>{{p.id}} · {{p.origin==='contemporary'?'当代共创':'传统资料'}}</small><h3>{{p.name}}</h3><p>{{p.imagery.filter((i:any)=>i.category==='文化意象').map((i:any)=>i.word).slice(0,2).join(' · ')}}</p></button></div><p v-if="!patterns.length">未找到匹配纹样，试试“莲花”“客家”或清除筛选。</p></main>
<main v-else-if="page==='detail'&&detail" class="content"><button class="text-button" @click="go('library')">← 返回基因库</button><div class="detail-head"><div><p class="eyebrow">{{detail.id}} / 纹样档案</p><h1 class="page-title">{{detail.name}}</h1><p class="subtle">来源：{{detail.document}}</p></div><button v-if="detail.genes.some(canUseGene)" class="primary" @click="usePattern(detail.id)">用此纹样设计 ↗</button><span v-else class="subtle">原始档案 · 供阅读与研究</span></div><section v-if="detail.origin==='contemporary'" class="contemporary-detail"><img :src="detail.images[0]?.url" :alt="detail.name"><div><p class="kicker">当代创作 · {{detail.creation_method==='remix'?'延续旧作':'独立绘制'}}</p><h2>{{detail.name}}</h2><p>{{detail.description}}</p><p>{{detail.semantic_status}}</p><button class="primary" @click="editCommunity(detail)">打开笔画，继续创作 ↗</button><button v-if="detail.source_design_id" @click="go(detail.source_design_id)">查看底稿设计</button><button v-if="detail.source_pattern_id" @click="openPattern(detail.source_pattern_id)">查看上一版作品</button><section v-if="detail.knowledge_refs?.length" class="asset-knowledge-refs"><h3>随作品保留的知识参考</h3><article v-for="a in detail.knowledge_refs"><button @click="readArticle(a.id)">{{a.title}} ↗</button><p>{{a.source_scope||a.source}}</p><a v-for="r in a.source_refs" :href="r.url" target="_blank" rel="noopener noreferrer">{{r.organization}} · {{r.title}} ↗</a></article></section><div v-if="detail.source_refs?.length" class="lineage-references"><span>继承的来源谱系</span><button v-for="r in detail.source_refs" @click="openPattern(r.pattern)">{{r.pattern}} · {{r.code||r.name}}<small>版本 {{r.version?.slice(0,12)}}</small></button></div></div></section><PatternReading v-else :pattern="detail" @create="usePattern"/><details class="gene-inventory"><summary>完整基因目录 · {{detail.genes.length}} 条</summary><div class="gene-grid" :class="{'is-contemporary':detail.origin==='contemporary'}"><article v-for="g in detail.genes" :key="g.code"><img v-if="g.assets[0]" :src="g.assets[0].url" :alt="g.name"><small>{{g.code}} · {{g.status}}</small><h3>{{g.name}}</h3><p>{{g.structure}}</p><span class="tag">{{g.type}}</span></article></div></details><h2>知意 · 意象与证据</h2><div class="chips"><span class="tag" v-for="i in detail.imagery">{{i.category}} / {{i.word}} · {{i.status}}</span></div><div class="table-wrap"><table><thead><tr><th>基因</th><th>关系与证据</th><th>权重</th><th>状态</th></tr></thead><tbody><tr v-for="r in detail.relations"><td>{{r.gene}}</td><td>{{r.type}} · {{r.evidence}}</td><td>{{r.weight}}</td><td>{{r.status}}</td></tr></tbody></table></div></main>
<main v-else-if="page==='saved'" class="content"><p class="eyebrow">COLLECTION / 藏纹</p><h1 class="page-title">作品集</h1><p class="subtle">这里收存着大家的创作。打开一份作品，沿着原有配方继续设计。</p><div class="cards"><button class="pattern-card" v-for="d in saved" @click="restore(d)"><div class="pattern-art is-saved-svg" v-html="d.svg"></div><small>{{d.id}}</small><h3>{{d.name}}</h3></button></div><div v-if="!saved.length" class="collection-empty"><p>还没有收存的作品。</p><button class="primary" @click="go('studio')">开始我的第一件作品 →</button></div></main>
<main v-else-if="page==='admin'" class="content"><p class="eyebrow">ARCHIVE MANAGEMENT / 资料管理</p><h1 class="page-title">文档入库与质量记录</h1><form class="search" @submit.prevent="admin"><input type="password" v-model="token" placeholder="输入部署时配置的后台密码" aria-label="后台密码" autocomplete="current-password"><button class="primary">进入后台</button></form><template v-if="report"><div class="data-strip"><div v-for="(v,k) in report.stats"><strong>{{v}}</strong><span>{{k}}</span></div></div><h2>上传／重新处理文档</h2><p>文件名须以PAT编号开头，仅支持DOCX，最大20MB。同编号将更新资料，既有设计保留资产快照。</p><input type="file" accept=".docx" @change="file=($event.target as HTMLInputElement).files?.[0]"><button :disabled="!file||busy" @click="upload">上传并解析</button><button @click="admin">刷新状态</button><h2>打样需求队列</h2><article v-for="r in requests" class="workshop-row"><h3>{{r.design_id}} · {{r.quantity}} 件</h3><p>{{r.contact||'未留联系方式'}} · {{r.notes}}</p><span>当前状态：{{r.status}}</span><select :value="r.status" @change="updateRequest(r.id,($event.target as HTMLSelectElement).value)"><option value="pending">待处理</option><option value="contacting">沟通中</option><option value="sampling">试制中</option><option value="completed">已完成</option><option value="returned">已退回</option></select><small>{{r.id}}</small></article><p v-if="!requests.length">暂无打样需求。</p><h3>文档处理任务</h3><pre>{{JSON.stringify(report.jobs,null,2)}}</pre><details><summary>编码冲突（{{report.conflicts.length}}）</summary><pre>{{JSON.stringify(report.conflicts,null,2)}}</pre></details><details><summary>资产异常与失败记录</summary><pre>{{JSON.stringify({errors:report.errors,issues:report.issues},null,2)}}</pre></details></template></main>
</div><footer class="app-footer"><a href="#studio" @click.prevent="go('studio')" class="footer-brand">锡语华纹 <span>一纹一器，一世心意。</span></a><div><a href="#community" @click.prevent="go('community')">当代创作库</a><a href="#library" @click.prevent="go('library')">查阅纹样</a><a href="#knowledge" @click.prevent="go('knowledge')">走近锡镶</a><a href="#admin" @click.prevent="go('admin')">资料管理</a></div></footer></div></template>
